const path = require('path');
const pptxgen = require('pptxgenjs');
const html2pptx = require('/Users/henry/.claude/plugins/cache/anthropic-agent-skills/document-skills/69c0b1a06741/skills/pptx/scripts/html2pptx.js');

async function createPresentation() {
  const pptx = new pptxgen();
  pptx.layout = 'LAYOUT_16x9';
  pptx.author = '浮浮酱 (AI 分析师)';
  pptx.title = '2025金融市场展望与投资策略 - 秒懂金融研究报告';

  const slidesDir = path.join(__dirname, 'slides-v2');

  // Slide 1: Title
  await html2pptx(path.join(slidesDir, 'slide01-title.html'), pptx);

  // Slide 2: Executive Summary with charts
  const { slide: slide2, placeholders: p2 } = await html2pptx(path.join(slidesDir, 'slide02-executive.html'), pptx);

  // Pie chart for asset allocation
  slide2.addChart(pptx.charts.PIE, [{
    name: "哑铃型配置",
    labels: ["硬科技成长", "高红利防守"],
    values: [50, 50]
  }], {
    ...p2[0],
    showPercent: true,
    showLegend: true,
    legendPos: 'b',
    chartColors: ["4472C4", "D4AF37"]
  });

  // Doughnut chart for keywords
  slide2.addChart(pptx.charts.DOUGHNUT, [{
    name: "2025关键词",
    labels: ["流动性改善", "技术革新", "价值重估"],
    values: [35, 40, 25]
  }], {
    ...p2[1],
    showPercent: true,
    showLegend: true,
    legendPos: 'b',
    chartColors: ["70AD47", "4472C4", "D4AF37"]
  });

  // Slide 3: Macro with line chart
  const { slide: slide3, placeholders: p3 } = await html2pptx(path.join(slidesDir, 'slide03-macro.html'), pptx);

  // Line chart for GDP trend
  slide3.addChart(pptx.charts.LINE, [{
    name: "GDP增长率",
    labels: ["2021", "2022", "2023", "2024E", "2025E"],
    values: [8.1, 3.0, 5.2, 4.9, 5.0]
  }, {
    name: "CPI",
    labels: ["2021", "2022", "2023", "2024E", "2025E"],
    values: [0.9, 2.0, 0.2, 1.5, 2.5]
  }], {
    ...p3[0],
    showLegend: true,
    legendPos: 'b',
    lineSize: 3,
    lineSmooth: true,
    showCatAxisTitle: true,
    catAxisTitle: '年份',
    showValAxisTitle: true,
    valAxisTitle: '百分比 (%)',
    valAxisMinVal: 0,
    valAxisMaxVal: 10,
    valAxisMajorUnit: 2,
    chartColors: ["4472C4", "D4AF37"]
  });

  // Slide 4: Gold with bar chart
  const { slide: slide4, placeholders: p4 } = await html2pptx(path.join(slidesDir, 'slide04-gold.html'), pptx);

  // Bar chart for gold price
  slide4.addChart(pptx.charts.BAR, [{
    name: "金价 (美元/盎司)",
    labels: ["2020", "2021", "2022", "2023", "2024", "2025E"],
    values: [1900, 1830, 1820, 1950, 2100, 2300]
  }], {
    ...p4[0],
    barDir: 'col',
    showTitle: true,
    title: '金价走势预测 (2020-2025)',
    showLegend: false,
    showCatAxisTitle: true,
    catAxisTitle: '年份',
    showValAxisTitle: true,
    valAxisTitle: '美元/盎司',
    valAxisMinVal: 1500,
    valAxisMaxVal: 2500,
    valAxisMajorUnit: 250,
    chartColors: ["D4AF37"],
    dataLabelPosition: 'outEnd',
    dataLabelColor: '1C2833'
  });

  // Slide 5: Tech with column chart
  const { slide: slide5, placeholders: p5 } = await html2pptx(path.join(slidesDir, 'slide05-tech.html'), pptx);

  // Column chart for AI market size
  slide5.addChart(pptx.charts.BAR, [{
    name: "AI市场规模 (亿元)",
    labels: ["2022", "2023", "2024E", "2025E", "2026E"],
    values: [2800, 4500, 7200, 11000, 16000]
  }], {
    ...p5[0],
    barDir: 'col',
    showTitle: true,
    title: '中国AI市场规模预测',
    showLegend: false,
    showCatAxisTitle: true,
    catAxisTitle: '年份',
    showValAxisTitle: true,
    valAxisTitle: '亿元',
    valAxisMinVal: 0,
    valAxisMaxVal: 18000,
    valAxisMajorUnit: 3000,
    chartColors: ["4472C4"],
    dataLabelPosition: 'outEnd'
  });

  // Slide 6: Dividend with horizontal bar chart
  const { slide: slide6, placeholders: p6 } = await html2pptx(path.join(slidesDir, 'slide06-dividend.html'), pptx);

  // Horizontal bar chart for dividend yields
  slide6.addChart(pptx.charts.BAR, [{
    name: "股息率 (%)",
    labels: ["银行", "能源", "公用事业", "电信", "房地产"],
    values: [6.5, 7.2, 5.8, 5.5, 4.9]
  }], {
    ...p6[0],
    barDir: 'bar',
    showTitle: true,
    title: '各行业股息率对比',
    showLegend: false,
    showCatAxisTitle: true,
    catAxisTitle: '行业',
    showValAxisTitle: true,
    valAxisTitle: '股息率 (%)',
    valAxisMinVal: 0,
    valAxisMaxVal: 9,
    valAxisMajorUnit: 1.5,
    chartColors: ["70AD47", "5A8F37", "4A7527", "3A6117", "2A4D0F"],
    dataLabelPosition: 'outEnd'
  });

  // Slide 7: Conclusion (no charts)
  await html2pptx(path.join(slidesDir, 'slide07-conclusion.html'), pptx);

  const outputPath = path.join(__dirname, '2025金融市场展望与投资策略-v2.pptx');
  await pptx.writeFile({ fileName: outputPath });

  console.log('✓ Presentation created:', outputPath);
  console.log('✓ Enhanced with charts, data visualizations, and improved layout');
}

createPresentation().catch(console.error);

